"""日志轮转。

按序号滚动日志文件：``app.log`` → ``app.log.1`` → ``app.log.2`` ……，
并按保留份数把最老的那些删掉。

``rotate`` 被实现成一个「要么全部完成、要么整体撤销」的事务：

* 搬运从最大序号往最小序号做，这样每一步的目标序号都已经腾出来了；
* 万一目标序号上还压着上一轮异常退出留下的残留文件，残留会先被挪到
  一个备份名上，整轮成功后再删除，失败则原样放回；
* 任何一步抛异常都会把已经完成的搬运逆向撤销，目录回到调用前的样子。
"""

import os

from . import fsutil
from .errors import RotationError

#: 临时挪开残留文件时使用的后缀。它不含纯数字后缀，因此不会被
#: :func:`fsutil.rotation_names` 误认成一个轮转世代。
BACKUP_SUFFIX = ".wrotate-backup"


class Rotator(object):
    """一个日志文件的轮转器。"""

    def __init__(self, path, keep=5):
        self.path = os.path.abspath(path)
        self.keep = int(keep)

    @property
    def directory(self):
        return os.path.dirname(self.path)

    @property
    def stem(self):
        return os.path.basename(self.path)

    def rotations(self):
        """返回当前存在的轮转文件名（按序号升序）。"""
        return fsutil.rotation_names(self.directory, self.stem)

    def rotate(self):
        """把当前日志滚成 ``.1``，并把已有轮转依次后移。

        返回本次被写入的新路径列表。

        ``app.log`` 不存在时是空操作，直接返回 ``[]``。中途失败时已经
        完成的搬运会被全部撤销，并把原始异常继续抛出。
        """
        if not os.path.exists(self.path):
            return []

        # 计划按序号升序生成：已有轮转依次后移，最后才是当前日志滚成 .1。
        # 返回值沿用这个顺序（既有语义），执行时才反过来。
        shifts = []
        for name in self.rotations():
            index = fsutil.rotation_index(name)
            src = os.path.join(self.directory, name)
            shifts.append((src, "%s.%d" % (self.path, index + 1)))
        current = (self.path, "%s.1" % self.path)

        done = []
        try:
            # 先搬序号最大的，再一路往下搬，最后才动当前日志。这样每一步的
            # 目标序号都已经被前一步腾空，不会把还没搬走的世代覆盖掉。
            for src, dst in reversed(shifts):
                done.append(self._step(src, dst))
            done.append(self._step(*current))
        except Exception:
            self._rollback(done)
            raise
        self._drop_backups(done)

        return [dst for _, dst in shifts] + [current[1]]

    def prune(self):
        """删除超出保留份数的轮转文件，返回被删除的名字列表。

        删除顺序按**序号**从大到小：按文件名字典序排的话 ``app.log.10``
        会排在 ``app.log.2`` 前面，保留 10 份时反而删掉了 ``app.log.1``。
        """
        ordered = sorted(self.rotations(), key=fsutil.rotation_index, reverse=True)
        keep = max(0, self.keep)
        removed = []
        for name in ordered[keep:]:
            if fsutil.remove(os.path.join(self.directory, name)):
                removed.append(name)
        return removed

    def rotate_and_prune(self):
        """轮转并立刻整理保留份数。"""
        moved = self.rotate()
        if not moved:
            raise RotationError("nothing to rotate: %s" % self.path)
        self.prune()
        return moved

    # -- 事务内部 ---------------------------------------------------------

    def _step(self, src, dst):
        """执行一步搬运，返回可用于回滚的记录 ``(src, dst, backup)``。

        目标序号上如果还压着残留文件，先把它挪到备份名上：一来这一步不会
        因为目标已存在而失败，二来回滚时还能把它原样放回去。
        """
        backup = None
        if os.path.lexists(dst):
            backup = self._backup_name(dst)
            # 这是事务内部的暂存动作，刻意不走 fsutil.move，免得干扰调用方
            # 对 fsutil.move 的注入/计数。
            os.replace(dst, backup)
        fsutil.move(src, dst)
        return (src, dst, backup)

    def _backup_name(self, dst):
        """为 ``dst`` 挑一个当前没人占用的备份名。"""
        candidate = dst + BACKUP_SUFFIX
        counter = 1
        while os.path.lexists(candidate):
            candidate = "%s.%d%s" % (dst, counter, BACKUP_SUFFIX)
            counter += 1
        return candidate

    def _rollback(self, done):
        """把已经完成的搬运逆向撤销（尽力而为，不再抛新异常）。"""
        for src, dst, backup in reversed(done):
            try:
                if os.path.lexists(dst) and not os.path.lexists(src):
                    os.replace(dst, src)
            except OSError:
                pass
            if backup is None:
                continue
            try:
                if os.path.lexists(backup):
                    os.replace(backup, dst)
            except OSError:
                pass

    def _drop_backups(self, done):
        """整轮成功后丢掉为残留文件建的备份。"""
        for _, _, backup in done:
            if backup is not None:
                fsutil.remove(backup)

